COMMENT ON TABLE vervent.asset_summary IS 'Vervent AssetSummary daily report: one row per asset (vehicle or deficiency-balance asset) per as-of date.';
COMMENT ON COLUMN vervent.asset_summary.lease_no_norm IS 'Derived: lease with any follow-on letter suffix normalized to the parent lease number';
COMMENT ON COLUMN vervent.asset_summary.state IS 'State where the asset is located';
COMMENT ON COLUMN vervent.asset_summary.lease IS 'Contract number; follow-on contracts carry a letter suffix (e.g. 500069007D = deficiency balance on 5000069007)';
COMMENT ON COLUMN vervent.asset_summary.asset_no IS 'LeasePak asset number';
COMMENT ON COLUMN vervent.asset_summary.port IS 'Portfolio code (50 = Camber)';
COMMENT ON COLUMN vervent.asset_summary.comp IS 'Company code';
COMMENT ON COLUMN vervent.asset_summary.reg IS 'Region code';
COMMENT ON COLUMN vervent.asset_summary.off IS 'Office code (100, DEF = deficiency)';
COMMENT ON COLUMN vervent.asset_summary.name IS 'Customer/obligor name';
COMMENT ON COLUMN vervent.asset_summary.term IS 'Lease term in months';
COMMENT ON COLUMN vervent.asset_summary.ls_type IS 'Lease type code (code_set ls_type)';
COMMENT ON COLUMN vervent.asset_summary.description IS 'Booked asset description';
COMMENT ON COLUMN vervent.asset_summary.acquis_date IS 'Date the asset was funded';
COMMENT ON COLUMN vervent.asset_summary.sold_date IS 'Asset sale date';
COMMENT ON COLUMN vervent.asset_summary.orig_cost IS 'Original equipment cost per asset';
COMMENT ON COLUMN vervent.asset_summary.status IS 'Asset status code (code_set asset_status)';
COMMENT ON COLUMN vervent.asset_summary.status_date IS 'Date of last asset status change';
COMMENT ON COLUMN vervent.asset_summary.dealer IS 'Dealer (vendor) code';
COMMENT ON COLUMN vervent.asset_summary.contr_status IS 'Contract status code (code_set ls_status)';
COMMENT ON COLUMN vervent.asset_summary.udf13 IS 'Asset UDF13 (dictionary: ''not sure if needed''); carries a list price / MSRP-like amount in the sample';
COMMENT ON COLUMN vervent.asset_summary.tax_code IS 'Taxing entities in effect (code_set use_tax_code)';
COMMENT ON COLUMN vervent.asset_summary.class IS 'Equipment class code';
COMMENT ON COLUMN vervent.asset_summary.orig_rcvbl IS 'Original receivable';
COMMENT ON COLUMN vervent.asset_summary.residual IS 'Total residual value';
COMMENT ON COLUMN vervent.asset_summary.guaranteed IS 'Guaranteed portion of the residual';
COMMENT ON COLUMN vervent.asset_summary.lessee_no IS 'Lessee number';
COMMENT ON COLUMN vervent.asset_summary.inventory IS 'Inventoried value';
COMMENT ON COLUMN vervent.asset_summary.orig_contr_no IS 'Contract UDF7 - original contract number';
COMMENT ON COLUMN vervent.asset_summary.new_used IS 'N = new, U = used';
COMMENT ON COLUMN vervent.asset_summary.rental_income IS 'Rental income YTD';
COMMENT ON COLUMN vervent.asset_summary.resi_income IS 'Residual income YTD';
COMMENT ON COLUMN vervent.asset_summary.interest_income IS 'Interest income YTD';
COMMENT ON COLUMN vervent.asset_summary.sale_proceeds IS 'Proceeds of the asset sale';
COMMENT ON COLUMN vervent.asset_summary.asset_as_sched IS 'Share of the contract''s original cost represented by this asset';
COMMENT ON COLUMN vervent.asset_summary.serial_number IS 'VIN for vehicles; the contract number for deficiency-balance assets';
COMMENT ON COLUMN vervent.asset_summary.inv_comment IS 'Asset UDF1';
COMMENT ON COLUMN vervent.asset_summary.eheld_orig_contr IS 'Asset UDF2 (mislabeled header; holds an amount in the sample)';
COMMENT ON COLUMN vervent.asset_summary.eheld_cust_name IS 'Asset UDF3 (mislabeled header; holds a m/d/yy date string in the sample)';
COMMENT ON COLUMN vervent.asset_summary.eheld_lessee IS 'Asset UDF4 - equipment model year (mislabeled header)';
COMMENT ON COLUMN vervent.asset_summary.eheld_return IS 'Asset UDF5 - equipment manufacturer / make (mislabeled header)';
COMMENT ON COLUMN vervent.asset_summary.curr_repo_status IS 'Repo status code (code_set repo_code)';
COMMENT ON COLUMN vervent.asset_summary.curr_repo_status_date IS 'Delivered as YYMMDD';
COMMENT ON COLUMN vervent.asset_summary.sec_note IS 'Asset UDF31';
COMMENT ON COLUMN vervent.asset_summary.allow_ppt_assmt IS 'Property tax assessed on this asset';
COMMENT ON COLUMN vervent.asset_summary.report_ppt IS 'Asset appears on the property tax assessor''s report';
COMMENT ON COLUMN vervent.asset_summary.annual_monthly IS 'Contract UDF33: A = annual, M = manual';
COMMENT ON COLUMN vervent.asset_summary.upfront_stax_yn IS 'Sales tax charged at lease start';
COMMENT ON COLUMN vervent.asset_summary.repo_code IS 'code_set repo_code';
COMMENT ON COLUMN vervent.asset_summary.on_hand IS 'Asset UDF30';
