CREATE INDEX IF NOT EXISTS contract_summary_lease_no_norm_idx ON vervent.contract_summary (lease_no_norm);
CREATE INDEX IF NOT EXISTS contract_summary_ls_status_idx ON vervent.contract_summary (ls_status);
CREATE INDEX IF NOT EXISTS contract_summary_account_key_idx ON vervent.contract_summary (account_key);
COMMENT ON TABLE vervent.contract_summary IS 'Vervent Contract Summary daily report: one row per contract (lease) per as-of date.';
COMMENT ON COLUMN vervent.contract_summary.lease_no_norm IS 'Derived: lease_no with any follow-on letter suffix normalized to the parent lease number';
COMMENT ON COLUMN vervent.contract_summary.next_billing_date_key IS 'Delivered as MM/DD/YYYY despite the Key name';
COMMENT ON COLUMN vervent.contract_summary.last_due_date_key IS 'CSV header LastDueDate (YYYYMMDD); _key suffix avoids clashing with LAST PAID DATE style columns';
COMMENT ON COLUMN vervent.contract_summary.last_paid_date_key IS 'CSV header LastPaidDate (YYYYMMDD); see also last_paid_date';
COMMENT ON COLUMN vervent.contract_summary.next_due_date_key IS 'CSV header NextDueDate (MM/DD/YYYY); see also next_due';
COMMENT ON COLUMN vervent.contract_summary.lease_no IS 'Contract number; follow-on contracts carry a letter suffix';
COMMENT ON COLUMN vervent.contract_summary.ls_status IS 'Lease status code (code_set ls_status)';
COMMENT ON COLUMN vervent.contract_summary.account_status IS 'Active / Closed';
COMMENT ON COLUMN vervent.contract_summary.last_update IS 'Date of last cash posting, reversal, etc.';
COMMENT ON COLUMN vervent.contract_summary.accrual_method IS 'code_set accrual_method';
COMMENT ON COLUMN vervent.contract_summary.class IS 'Equipment class code (V, EDEF); text as in asset_summary';
COMMENT ON COLUMN vervent.contract_summary.ls_type IS 'code_set ls_type';
COMMENT ON COLUMN vervent.contract_summary.stmt_code IS 'Statement format';
COMMENT ON COLUMN vervent.contract_summary.use_tax_code IS 'code_set use_tax_code';
COMMENT ON COLUMN vervent.contract_summary.late_code IS 'code_set late_code';
COMMENT ON COLUMN vervent.contract_summary.open_closed IS 'End-of-term condition: O = open-end, C = closed-end';
COMMENT ON COLUMN vervent.contract_summary.oec IS 'Original equipment cost';
COMMENT ON COLUMN vervent.contract_summary.orig_idc IS 'Original initial direct cost';
COMMENT ON COLUMN vervent.contract_summary.orig_ue_resid IS 'Original unearned residual income';
COMMENT ON COLUMN vervent.contract_summary.tot_residual IS 'Unguaranteed + guaranteed residual';
COMMENT ON COLUMN vervent.contract_summary.security_d IS 'Security deposit';
COMMENT ON COLUMN vervent.contract_summary.contract_rcvbl IS 'Remaining lease payments + guaranteed residual';
COMMENT ON COLUMN vervent.contract_summary.remaining_interest IS 'Duplicate of remaining unearned income';
COMMENT ON COLUMN vervent.contract_summary.lsor_remain_ue IS 'Current remaining unearned income';
COMMENT ON COLUMN vervent.contract_summary.nbv IS 'Net book value';
COMMENT ON COLUMN vervent.contract_summary.resi_income IS 'Residual income, current period';
COMMENT ON COLUMN vervent.contract_summary.pap IS 'Pre-authorized payment';
COMMENT ON COLUMN vervent.contract_summary.days_del IS 'Days delinquent';
COMMENT ON COLUMN vervent.contract_summary.curr_delinq IS 'Delinquency age bucket';
COMMENT ON COLUMN vervent.contract_summary.num_30_del IS 'Times 16-30 days delinquent';
COMMENT ON COLUMN vervent.contract_summary.num_60_del IS 'Times 31-60 days delinquent';
COMMENT ON COLUMN vervent.contract_summary.num_90_del IS 'Times 61-90 days delinquent';
COMMENT ON COLUMN vervent.contract_summary.num_91_plus_del IS 'Times 91+ days delinquent';
COMMENT ON COLUMN vervent.contract_summary.ls_source IS 'code_set ls_source';
COMMENT ON COLUMN vervent.contract_summary.coll_code IS 'Collection status (code_set coll_code)';
COMMENT ON COLUMN vervent.contract_summary.coll_date IS 'Free-text date entry; mixed formats (YYYYMMDD, MMDDYY, MM.DD.YYYY, MM/DD/YYYY) and invalid values, so kept raw';
COMMENT ON COLUMN vervent.contract_summary.curr_pymt IS 'Current monthly payment';
COMMENT ON COLUMN vervent.contract_summary.prin_pd_ltd IS 'Principal paid life to date';
COMMENT ON COLUMN vervent.contract_summary.field10_s IS 'Unlabeled column between CONTR UDF 10 and 11 (Y/N in the sample)';
COMMENT ON COLUMN vervent.contract_summary.contr_udf_20_1 IS 'Second column labeled CONTR UDF 20 in the file';
COMMENT ON COLUMN vervent.contract_summary.as_of_date IS 'System date of report generation';
COMMENT ON COLUMN vervent.contract_summary.remaining_payments IS 'Fractional count of payments left';
COMMENT ON COLUMN vervent.contract_summary.down IS 'Outstanding down payment balance';

-- -----------------------------------------------------------------------------
-- vervent.transaction_history
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS vervent.transaction_history (
  file_id                     integer NOT NULL REFERENCES vervent.report_file (file_id) ON DELETE CASCADE,
  asof_date                   date NOT NULL,
  transaction_key             bigint NOT NULL,  -- CSV: TransactionKey
  portfolio                   smallint,  -- CSV: Portfolio
  report_key                  text,  -- CSV: REPORTKEY
  transaction_date_key        date,  -- CSV: TransactionDateKey
  effective_date_key          date,  -- CSV: EffectiveDateKey
  date_due_date_key           date,  -- CSV: DateDueDateKey
  is_payoff                   boolean,  -- CSV: IsPayoff
  is_non_cash                 boolean,  -- CSV: IsNonCash
  is_past_due                 boolean,  -- CSV: IsPastDue
  is_cash_report_transaction  boolean,  -- CSV: IsCashReportTransaction
  contract_number             text NOT NULL,  -- CSV: CONTRACTNUMBER
  name                        text,  -- CSV: NAME
  description                 text,  -- CSV: DESCRIPTION
  trans                       text,  -- CSV: TRANS
  bankcd                      text,  -- CSV: BANKCD
  debit_vector                integer,  -- CSV: DEBIT VECTOR
  credit_vector               integer,  -- CSV: CREDIT VECTOR
  checkno                     text,  -- CSV: CHECKNO
  posted_date                 date,  -- CSV: POSTEDDATE
  invoice_due_date            date,  -- CSV: INVOICEDUEDATE
  transaction_amount          numeric(14,2),  -- CSV: TRANSACTIONAMOUNT
  payment                     numeric(14,2),  -- CSV: PAYMENT
  prepayment                  numeric(14,2),  -- CSV: PREPAYMENT
  payoff                      numeric(14,2),  -- CSV: PAYOFF
  inventory_sale              numeric(14,2),  -- CSV: INVENTORYSALE
  paydown                     numeric(14,2),  -- CSV: PAYDOWN
  property_tax                numeric(14,2),  -- CSV: PROPERTYTAX
  sales_tax                   numeric(14,2),  -- CSV: SALESTAX
  late_charge                 numeric(14,2),  -- CSV: LATECHARGE
  collection_fee              numeric(14,2),  -- CSV: COLLECTIONFEE
  assumption_fee              numeric(14,2),  -- CSV: ASSUMPTIONFEE
  legal_fee                   numeric(14,2),  -- CSV: LEGALFEE
  pmt_extension               numeric(14,2),  -- CSV: PMTEXTENSION
  lse_extension               numeric(14,2),  -- CSV: LSEEXTENSION
  itc_fees                    numeric(14,2),  -- CSV: ITCFEES
  fhut                        numeric(14,2),  -- CSV: FHUT
  idr                         numeric(14,2),  -- CSV: IDR
  lease_rewrite               numeric(14,2),  -- CSV: LEASEREWRITE
  other_fees                  numeric(14,2),  -- CSV: OTHERFEES
  security_deposit            numeric(14,2),  -- CSV: SECURITYDEPOSIT
  suspense                    numeric(14,2),  -- CSV: SUSPENSE
  rcr1                        numeric(14,2),  -- CSV: RCR1
  rcr2                        numeric(14,2),  -- CSV: RCR2
  rcr3                        numeric(14,2),  -- CSV: RCR3
  payment_amount              numeric(14,2),  -- CSV: PAYMENTAMOUNT
  operinits                   text,  -- CSV: OPERINITS
  lease_no_norm               text GENERATED ALWAYS AS (vervent.norm_lease_no(contract_number)) STORED,
  loaded_at                   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (transaction_key)
);
CREATE INDEX IF NOT EXISTS transaction_history_lease_no_norm_idx ON vervent.transaction_history (lease_no_norm);
CREATE INDEX IF NOT EXISTS transaction_history_contract_number_posted_date_idx ON vervent.transaction_history (contract_number, posted_date);
CREATE INDEX IF NOT EXISTS transaction_history_asof_date_idx ON vervent.transaction_history (asof_date);
COMMENT ON TABLE vervent.transaction_history IS 'Vervent TransactionHistory report: one row per posted transaction. Daily files carry the prior day''s activity, monthly files the whole month; transaction_key is the identity so overlapping files upsert.';
COMMENT ON COLUMN vervent.transaction_history.lease_no_norm IS 'Derived: contract_number with any follow-on letter suffix normalized to the parent lease number';
COMMENT ON COLUMN vervent.transaction_history.report_key IS 'Portfolio / company / region / office';
COMMENT ON COLUMN vervent.transaction_history.contract_number IS 'Contract number; follow-on contracts carry a letter suffix';
COMMENT ON COLUMN vervent.transaction_history.description IS 'Transaction code description';
COMMENT ON COLUMN vervent.transaction_history.trans IS 'Transaction code (code_set tran_code)';
COMMENT ON COLUMN vervent.transaction_history.bankcd IS 'Bank code (code_set bank_code)';
COMMENT ON COLUMN vervent.transaction_history.debit_vector IS 'Debit GL vector (gl_vector)';
COMMENT ON COLUMN vervent.transaction_history.credit_vector IS 'Credit GL vector (gl_vector)';
COMMENT ON COLUMN vervent.transaction_history.payment IS 'Principal/interest payments';
COMMENT ON COLUMN vervent.transaction_history.fhut IS 'Federal highway use tax';
COMMENT ON COLUMN vervent.transaction_history.idr IS 'Deferred interim rent / deferred lease fees';
COMMENT ON COLUMN vervent.transaction_history.rcr1 IS 'Recurring charge 1';
COMMENT ON COLUMN vervent.transaction_history.payment_amount IS 'Total payment amount posted';
COMMENT ON COLUMN vervent.transaction_history.operinits IS 'Operator initials';
